"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { PlusCircle, Search, Palette, Briefcase, ChevronRight } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { PageContainer, PageHeader } from "@/components/layout";
import { BrandCreateModal } from "@/components/brands/modals/brand-create-modal";
import { Skeleton } from "@/components/ui/skeleton";
import type { BrandProfile } from "@/types/brand-knowledge";
import { ROUTES } from "@/lib/constants";

export default function BrandsDashboardPage() {
  const [brands, setBrands] = useState<BrandProfile[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);

  async function fetchBrands() {
    setIsLoading(true);
    try {
      const res = await fetch("/api/brands");
      if (res.ok) {
        const data = await res.json();
        setBrands(data);
      }
    } catch (error) {
      console.error("Failed to fetch brands", error);
    } finally {
      setIsLoading(false);
    }
  }

  useEffect(() => {
    fetchBrands();
  }, []);

  const filteredBrands = brands.filter((brand) =>
    brand.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <PageContainer>
      <PageHeader 
        title="Brand Knowledge Base"
        description="Manage brand profiles, messaging, and visual assets."
      >
        <Button onClick={() => setIsCreateModalOpen(true)} className="gap-2">
          <PlusCircle className="h-4 w-4" />
          Create Brand
        </Button>
      </PageHeader>

      <div className="flex flex-col gap-6 p-6">
        <div className="flex items-center gap-4">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              placeholder="Search brands..."
              className="pl-9"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
        </div>

        {isLoading ? (
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            {[1, 2, 3].map((i) => (
              <Card key={i} className="overflow-hidden">
                <CardHeader className="pb-4">
                  <Skeleton className="h-6 w-3/4" />
                  <Skeleton className="h-4 w-1/2" />
                </CardHeader>
                <CardContent>
                  <div className="flex gap-2">
                    <Skeleton className="h-8 w-16 rounded-full" />
                    <Skeleton className="h-8 w-16 rounded-full" />
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        ) : filteredBrands.length > 0 ? (
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            {filteredBrands.map((brand) => (
              <Link key={brand.id} href={ROUTES.BRAND(brand.id)}>
                <Card className="group h-full cursor-pointer overflow-hidden border-border/50 transition-all hover:border-violet-500/50 hover:shadow-md hover:shadow-violet-500/10">
                  <CardHeader className="pb-4">
                    <div className="flex items-center justify-between">
                      <CardTitle className="line-clamp-1">{brand.name}</CardTitle>
                      <ChevronRight className="h-5 w-5 text-muted-foreground opacity-0 transition-opacity group-hover:opacity-100" />
                    </div>
                    <CardDescription>
                      Updated {new Date(brand.updatedAt).toLocaleDateString()}
                    </CardDescription>
                  </CardHeader>
                  <CardContent>
                    <div className="flex gap-2 text-xs text-muted-foreground">
                      <div className="flex items-center gap-1 rounded-md bg-secondary/50 px-2 py-1">
                        <Briefcase className="h-3 w-3" />
                        <span>v{brand.version}</span>
                      </div>
                      {/* We could show asset count here if the API returned it */}
                    </div>
                  </CardContent>
                </Card>
              </Link>
            ))}
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center rounded-xl border border-dashed p-12 text-center">
            <Palette className="mb-4 h-12 w-12 text-muted-foreground/50" />
            <h3 className="text-lg font-semibold">No brands found</h3>
            <p className="mb-6 max-w-sm text-sm text-muted-foreground">
              {searchQuery
                ? "No brands matched your search criteria."
                : "Create your first brand profile to start organizing assets and messaging."}
            </p>
            {searchQuery ? (
              <Button variant="outline" onClick={() => setSearchQuery("")}>
                Clear Search
              </Button>
            ) : (
              <Button onClick={() => setIsCreateModalOpen(true)} className="gap-2">
                <PlusCircle className="h-4 w-4" />
                Create Brand
              </Button>
            )}
          </div>
        )}
      </div>

      <BrandCreateModal 
        open={isCreateModalOpen} 
        onOpenChange={setIsCreateModalOpen}
        onCreated={fetchBrands}
      />
    </PageContainer>
  );
}
